import * as THREE from './three.module.js';
// Original ONE cartoon hand, generated once during preparation of V218.
// Indexed, continuous surface; decoded directly to avoid meshing on phones.
const positionsData="";
const normalsData="";
const indicesData="";
function bytes(text){const raw=atob(text),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out.buffer;}
export function cartoonHandGeometry(){const g=new THREE.BufferGeometry(),p=new Float32Array(bytes(positionsData)),q=new Int8Array(bytes(normalsData)),n=new Float32Array(q.length);for(let i=0;i<q.length;i+=3){const k=1/(Math.hypot(q[i],q[i+1],q[i+2])||1);n[i]=q[i]*k;n[i+1]=q[i+1]*k;n[i+2]=q[i+2]*k;}g.setAttribute('position',new THREE.BufferAttribute(p,3));g.setAttribute('normal',new THREE.BufferAttribute(n,3));g.setIndex(new THREE.BufferAttribute(new Uint16Array(bytes(indicesData)),1));g.computeBoundingSphere();return g;}
